"""No real desktop input is generated by these tests."""

import unittest
from pathlib import Path
from unittest import mock

import auto_paste as ap


class PasteShortcutTests(unittest.TestCase):
    def setUp(self):
        patcher = mock.patch.object(ap, "_MutterKeyboard")
        self.factory = patcher.start()
        self.addCleanup(patcher.stop)
        self.keyboard = self.factory.return_value.__enter__.return_value
        sleeper = mock.patch.object(ap.time, "sleep")
        self.sleep = sleeper.start()
        self.addCleanup(sleeper.stop)

    def test_emits_one_paste_and_releases_keys_without_enter(self):
        ap.paste_clipboard()
        self.assertEqual(self.keyboard.key.call_args_list, [
            mock.call(29, True), mock.call(47, True),
            mock.call(47, False), mock.call(29, False),
        ])
        self.factory.return_value.__exit__.assert_called_once()

    def test_uncertain_v_press_is_not_retried_and_both_keys_are_released(self):
        self.keyboard.key.side_effect = [None, RuntimeError("unavailable"), None, None]
        with self.assertRaises(RuntimeError):
            ap.paste_clipboard()
        self.assertEqual(self.keyboard.key.call_args_list, [
            mock.call(29, True), mock.call(47, True),
            mock.call(47, False), mock.call(29, False),
        ])
        self.factory.return_value.__exit__.assert_called_once()

    def test_uncertain_modifier_press_is_released_without_pressing_v(self):
        self.keyboard.key.side_effect = [RuntimeError("unavailable"), None]
        with self.assertRaises(RuntimeError):
            ap.paste_clipboard()
        self.assertEqual(self.keyboard.key.call_args_list, [
            mock.call(29, True), mock.call(29, False),
        ])

    def test_failed_release_still_releases_modifier_and_closes_session(self):
        self.keyboard.key.side_effect = [None, None, RuntimeError("lost"), None]
        with self.assertRaises(RuntimeError):
            ap.paste_clipboard()
        self.assertEqual(self.keyboard.key.call_args_list[-1], mock.call(29, False))
        self.factory.return_value.__exit__.assert_called_once()

    def test_unavailable_session_sends_no_input(self):
        self.factory.return_value.__enter__.side_effect = RuntimeError("unavailable")
        with self.assertRaises(RuntimeError):
            ap.paste_clipboard()
        self.keyboard.key.assert_not_called()

    def test_terminal_emits_one_ctrl_shift_v_and_releases_all_keys(self):
        ap.paste_clipboard(terminal=True)
        self.assertEqual(self.keyboard.key.call_args_list, [
            mock.call(29, True), mock.call(42, True), mock.call(47, True),
            mock.call(47, False), mock.call(42, False), mock.call(29, False),
        ])
        self.assertEqual(self.sleep.call_args_list, [
            mock.call(0.01), mock.call(0.01), mock.call(0.01), mock.call(0.04),
        ])

    def test_terminal_uncertain_press_releases_v_shift_and_control_without_retry(self):
        self.keyboard.key.side_effect = [None, None, RuntimeError("lost"), None, None, None]
        with self.assertRaises(RuntimeError):
            ap.paste_clipboard(terminal=True)
        self.assertEqual(self.keyboard.key.call_args_list, [
            mock.call(29, True), mock.call(42, True), mock.call(47, True),
            mock.call(47, False), mock.call(42, False), mock.call(29, False),
        ])


class TerminalDetectionTests(unittest.TestCase):
    def test_recognized_terminal_executable_selects_terminal_shortcut(self):
        with mock.patch.object(ap, "_active_application_pids", return_value=frozenset({123})), \
                mock.patch.object(ap.Path, "readlink", return_value=Path("/usr/bin/ptyxis")):
            self.assertTrue(ap.is_terminal_focused())

    def test_ordinary_application_keeps_existing_shortcut(self):
        with mock.patch.object(ap, "_active_application_pids", return_value=frozenset({123})), \
                mock.patch.object(ap.Path, "readlink", return_value=Path("/usr/bin/text-editor")):
            self.assertFalse(ap.is_terminal_focused())

    def test_missing_ambiguous_invalid_or_failed_metadata_is_not_a_terminal(self):
        for pids in (frozenset(), frozenset({1, 2}), frozenset({-1})):
            with self.subTest(pids=pids), mock.patch.object(ap, "_active_application_pids", return_value=pids), \
                    mock.patch.object(ap.Path, "readlink") as readlink:
                self.assertFalse(ap.is_terminal_focused())
                readlink.assert_not_called()
        with mock.patch.object(ap, "_active_application_pids", side_effect=TimeoutError):
            self.assertFalse(ap.is_terminal_focused())
        with mock.patch.object(ap, "_active_application_pids", return_value=frozenset({123})), \
                mock.patch.object(ap.Path, "readlink", side_effect=OSError):
            self.assertFalse(ap.is_terminal_focused())

    def test_preparation_freezes_shortcut_before_clipboard_changes_focus(self):
        with mock.patch.object(ap, "is_terminal_focused", return_value=True) as detect, \
                mock.patch.object(ap, "paste_clipboard") as paste:
            prepared = ap.AutomaticPaste().prepare()
            detect.assert_called_once_with()
            paste.assert_not_called()
            detect.return_value = False
            prepared()
            paste.assert_called_once_with(terminal=True)
            detect.assert_called_once_with()


class FocusMetadataTests(unittest.TestCase):
    @staticmethod
    def reply(value):
        response = mock.Mock()
        response.unpack.return_value = (value,)
        return response

    def test_shallow_probe_uses_active_state_and_peer_pid_only(self):
        connection = mock.Mock()
        connection.call_sync.side_effect = [
            self.reply([(':1.1', '/app')]),
            self.reply([(':1.1', '/window')]),
            self.reply([ap.ACTIVE_STATE_MASK, 0]),
            self.reply(123),
        ]
        with mock.patch.object(ap, "_connect_accessibility_bus", return_value=connection):
            self.assertEqual(ap._active_application_pids(), frozenset({123}))
        self.assertEqual([call.args[3] for call in connection.call_sync.call_args_list],
                         ['GetChildren', 'GetChildren', 'GetState', 'GetConnectionUnixProcessID'])
        connection.close_sync.assert_called_once_with(None)

    def test_focused_but_inactive_shell_window_does_not_select_terminal(self):
        connection = mock.Mock()
        connection.call_sync.side_effect = [
            self.reply([(':1.1', '/app')]),
            self.reply([(':1.1', '/window')]),
            self.reply([1 << 12, 0]),
        ]
        with mock.patch.object(ap, "_connect_accessibility_bus", return_value=connection):
            self.assertEqual(ap._active_application_pids(), frozenset())
        self.assertEqual(connection.call_sync.call_count, 3)

    def test_failed_metadata_closes_dedicated_connection(self):
        connection = mock.Mock()
        connection.call_sync.side_effect = RuntimeError("unavailable")
        with mock.patch.object(ap, "_connect_accessibility_bus", return_value=connection), \
                self.assertRaises(RuntimeError):
            ap._active_application_pids()
        connection.close_sync.assert_called_once_with(None)

    def test_budget_exhaustion_does_not_attempt_connection(self):
        with mock.patch.object(ap, "FOCUS_LOOKUP_SECONDS", -1), \
                mock.patch.object(ap, "_connect_accessibility_bus") as connect, \
                self.assertRaises(TimeoutError):
            ap._active_application_pids()
        connect.assert_not_called()

    def test_large_desktop_is_inconclusive_without_traversing_it(self):
        connection = mock.Mock()
        connection.call_sync.return_value = self.reply([(':1.1', '/app')] * 33)
        with mock.patch.object(ap, "_connect_accessibility_bus", return_value=connection):
            self.assertEqual(ap._active_application_pids(), frozenset())
        connection.call_sync.assert_called_once()
        connection.close_sync.assert_called_once_with(None)


class InputSessionCleanupTests(unittest.TestCase):
    def test_close_stops_session_and_closes_dedicated_connection(self):
        keyboard = ap._MutterKeyboard()
        connection = keyboard.connection = mock.Mock()
        keyboard.path = "/test/session"
        with mock.patch.object(keyboard, "_call") as call:
            keyboard.close()
        call.assert_called_once_with("/test/session", ap.SESSION_INTERFACE, "Stop")
        connection.close_sync.assert_called_once_with(None)
        self.assertIsNone(keyboard.connection)
        self.assertIsNone(keyboard.path)

    def test_failed_stop_still_closes_connection_and_clears_session(self):
        keyboard = ap._MutterKeyboard()
        connection = keyboard.connection = mock.Mock()
        keyboard.path = "/test/session"
        with mock.patch.object(keyboard, "_call", side_effect=RuntimeError("unavailable")):
            keyboard.close()
        connection.close_sync.assert_called_once_with(None)
        keyboard.close()  # Idempotent.
        connection.close_sync.assert_called_once()


if __name__ == "__main__":
    unittest.main()
